    def test_relatives(self, collection: Collection) -> None:
        parent = self.add_task(collection, summary="parent")
        data = Task.new(summary="child")
        data.component.add("RELATED-TO", parent.uid, parameters={"RELTYPE": "PARENT"})
        if level(collection, Feature.TASK_RELATIONS_PARENT) is Support.UNSUPPORTED:
            with pytest.raises(LossyWriteError):
                collection.add(data)
            return
        child = collection.add(data)
        assert [r.uid for r in child.relatives()] == [parent.uid]
        assert [r.uid for r in child.relatives("PARENT")] == [parent.uid]
        assert child.relatives("CHILD") == []
        assert [r.uid for r in parent.relatives()] == [child.uid]
        assert [r.uid for r in parent.relatives("CHILD")] == [child.uid]
        assert parent.relatives("PARENT") == []
        assert all(r.collection is collection for r in parent.relatives())

