    def test_changes_since_a_token(self, collection: Collection) -> None:
        if level(collection, Feature.CHANGES) is Support.UNSUPPORTED:
            self.assert_unsupported(
                collection, Feature.CHANGES, lambda: collection.changes(SyncToken("conformance-token"))
            )
            return
        keep, change, drop = [self.add_task(collection, summary=s) for s in ("keep", "change", "drop")]
        start = collection.changes()
        change.component["SUMMARY"] = "changed"
        change.save()
        drop.delete()
        added = collection.add_task(summary="added")
        since = collection.changes(start.token)
        assert {i.native_id for i in since.changed} == {change.native_id, added.native_id}
        assert since.deleted == [drop.native_id]
        assert keep.native_id not in since.deleted
        quiet = collection.changes(since.token)
        assert quiet.changed == []
        assert quiet.deleted == []

    def test_changes_against_known(self, collection: Collection) -> None:
        if level(collection, Feature.CHANGES) is Support.UNSUPPORTED:
            self.assert_unsupported(collection, Feature.CHANGES, lambda: collection.changes(known={}))
            return
        keep, change, drop = [self.add_task(collection, summary=s) for s in ("keep", "change", "drop")]
        known = {nid(i): str(i.etag) for i in (keep, change, drop)}
        if level(collection, Feature.CHANGES_KNOWN) is Support.UNSUPPORTED:
            self.assert_unsupported(collection, Feature.CHANGES_KNOWN, lambda: collection.changes(known=known))
            return
        change.component["SUMMARY"] = "changed"
        change.save()
        drop.delete()
        added = collection.add_task(summary="added")
        result = collection.changes(known=known)
        assert {i.native_id for i in result.changed} == {change.native_id, added.native_id}
        assert result.deleted == [drop.native_id]
        with pytest.raises(ValueError, match="known"):
            collection.changes(result.token, known=known)
        later = collection.add_task(summary="later")
        following = collection.changes(result.token)  # a known= token is a token like any other
        assert {i.native_id for i in following.changed} == {later.native_id}
        assert following.deleted == []

    def test_a_bad_token_raises(self, collection: Collection) -> None:
        if level(collection, Feature.CHANGES) is Support.UNSUPPORTED:
            self.assert_unsupported(
                collection, Feature.CHANGES, lambda: collection.changes(SyncToken("conformance-not-a-token"))
            )
            return
        with pytest.raises(SyncTokenError):
            collection.changes(SyncToken("conformance-not-a-token"))

    def test_a_token_from_another_collection_raises(
        self, backend: Backend, collection: Collection
    ) -> None:
        if level(collection, Feature.CHANGES) is Support.UNSUPPORTED:
            return  # test_a_bad_token_raises checked that changes() raises
        if not backend.capabilities.supports(Feature.CREATE_COLLECTION):
            pytest.skip("a second collection is needed, and the backend cannot make one")
        other = self.open_collection(backend, "conformance-other")
        if level(other, Feature.CHANGES) is Support.UNSUPPORTED:
            pytest.skip("the second collection has no change feed")
        token = (other.changes()).token
        with pytest.raises(SyncTokenError):
            collection.changes(token)

    # === time tracking ================================================

    def logged_against(self, collection: Collection) -> SyncItem:
        """A stored task (an event where there are no tasks) to log time against, or the test ends here."""
        kind = Component.TASK if holds(collection, Component.TASK) else Component.EVENT
        if not holds(collection, kind):
            pytest.skip("the collection holds neither tasks nor events")
        [item] = self.seed(collection, [KINDS[kind][0].new(summary="logged against", start=at(1, 8))])
        return item

    def assert_time_log_unsupported(self, collection: Collection, item: SyncItem) -> bool:
        """True if the time log is unsupported here, after checking that logging raises before any I/O."""
        if level(collection, Feature.TIME_LOG) is not Support.UNSUPPORTED:
            return False
        self.assert_unsupported(collection, Feature.TIME_LOG, lambda: item.log_time(spent=HOUR))
        self.assert_unsupported(collection, Feature.TIME_LOG, lambda: item.time_log())
        return True

    def lost(self, collection: Collection) -> set[str]:
        return set(collection.capabilities.details(Feature.TIME_LOG).get("lost", ()))

    def total_only(self, collection: Collection) -> bool:
        return bool(collection.capabilities.details(Feature.TIME_LOG).get("total-only"))

    def test_time_log_round_trips_as_declared(self, collection: Collection) -> None:
        item = self.logged_against(collection)
        if self.assert_time_log_unsupported(collection, item):
            return
        assert item.time_log() == []
        assert item.time_spent() == timedelta(0)
        if not writable(collection):
            self.assert_unsupported(collection, Feature.WRITE, lambda: item.log_time(spent=HOUR))
            return
        users = ("mailto:alice@example.com", "mailto:bob@example.com")
        logged = item.log_time(start=at(3, 9), end=at(3, 11), users=users, comment="first draft\nwith figures")
        assert logged.duration == 2 * HOUR
        assert not any(is_entry(r.component) for r in item.relatives()), "a time entry is no subtask"
        [read] = item.time_log()
        if self.total_only(collection):
            assert item.time_spent() == 4 * HOUR, "two people for two hours, kept as a total"
            assert read.start is None, "a total-only backend has no entries to give a start"
            return
        assert read.duration == 2 * HOUR
        if "users" not in self.lost(collection):
            assert item.time_spent() == 4 * HOUR, "person-time: two people for two hours"
        lost = self.lost(collection)
        expected: dict[str, tuple[object, object]] = {
            "start-time": (read.start, at(3, 9)),
            "end": (read.end, at(3, 11)),
        }
        expected |= {"users": (read.users, users), "comment": (read.comment, "first draft\nwith figures")}
        for name, (got, sent) in expected.items():
            if name in lost:
                assert got in (None, ()), f"{name} is declared lost, yet read back as {got!r}: never invent it"
            else:
                assert got == sent, f"{name}: sent {sent!r}, read back {got!r}"
        assert read.id is not None

    def test_log_time_takes_two_of_three(self, collection: Collection) -> None:
        item = self.logged_against(collection)
        if self.assert_time_log_unsupported(collection, item) or not writable(collection):
            return
        before = snapshot(collection)
        with pytest.raises(ValueError, match="disagree"):
            item.log_time(spent=3 * HOUR, start=at(3, 9), end=at(3, 11))
        with pytest.raises(ValueError, match="two of"):
            item.log_time(start=at(3, 9))
        assert snapshot(collection) == before, "a refused entry wrote something"
        by_start = item.log_time(spent=HOUR, start=at(3, 9))
        by_end = item.log_time(spent=HOUR, end=at(4, 11))
        recent = item.log_time(spent=HOUR)
        assert [e.duration for e in (by_start, by_end, recent)] == [HOUR] * 3
        assert item.time_spent() == 3 * HOUR
        if not self.total_only(collection) and "start-time" not in self.lost(collection):
            assert (by_start.start, by_start.end) == (at(3, 9), at(3, 10))
            assert (by_end.start, by_end.end) == (at(4, 10), at(4, 11))

    def test_a_day_of_durations_lines_up(self, collection: Collection) -> None:
        item = self.logged_against(collection)
        if self.assert_time_log_unsupported(collection, item) or not writable(collection):
            return
        tuesday = at(3).date()
        first = item.log_time(spent=3 * HOUR, day=tuesday)
        second = item.log_time(spent=2 * HOUR, day=tuesday)
        assert item.time_spent() == 5 * HOUR
        if self.total_only(collection) or "start-time" in self.lost(collection):
            return
        assert first.start is not None
        assert first.start.date() == tuesday
        assert second.start == first.end, "the day's entries line up back to back"

    def test_the_timer(self, collection: Collection) -> None:
        if not holds(collection, Component.TASK):
            pytest.skip("the timer is for tasks, and the collection holds none")
        [task] = self.seed(collection, [Task.new(summary="timed")])
        assert isinstance(task, SyncTask)
        if level(collection, Feature.TIME_LOG) is Support.UNSUPPORTED:
            self.assert_unsupported(collection, Feature.TIME_LOG, lambda: task.start_timer())
            return
        if not writable(collection):
            self.assert_unsupported(collection, Feature.WRITE, lambda: task.start_timer())
            return
        task.start_timer(at=at(3, 9))
        with pytest.raises(ValueError, match="running"):
            task.start_timer()
        reread = collection.reload(task)
        assert isinstance(reread, SyncTask)
        [running] = reread.time_log()
        assert running.running
        assert running.start == at(3, 9)
        entry = task.stop_timer(at=at(3, 10, 30), comment="done for now")
        assert entry.duration == timedelta(hours=1, minutes=30)
        with pytest.raises(ValueError, match="running"):
            task.stop_timer()
        [stored] = (collection.reload(task)).time_log()
        assert not stored.running
        assert stored.duration == timedelta(hours=1, minutes=30)
        assert "X-PYCAL-TIMER-START" not in (collection.reload(task)).component, "the timer is temporary"

    def test_amend_and_delete_time(self, collection: Collection) -> None:
        item = self.logged_against(collection)
        if self.assert_time_log_unsupported(collection, item) or not writable(collection):
            return
        entry = item.log_time(start=at(3, 9), end=at(3, 10), comment="first")
        if self.total_only(collection):
            [read] = item.time_log()
            self.assert_unsupported(collection, Feature.TIME_LOG, lambda: item.amend_time(read, comment="x"))
            self.assert_unsupported(collection, Feature.TIME_LOG, lambda: item.delete_time(read))
            return
        amended = item.amend_time(entry, spent=2 * HOUR)
        assert amended.duration == 2 * HOUR
        assert amended.id == entry.id
        [read] = item.time_log()
        assert read.duration == 2 * HOUR
        if "comment" not in self.lost(collection):
            assert read.comment == "first", "amending one field kept the others"
        item.delete_time(read)
        assert item.time_log() == []

    def test_time_spent_in_a_meeting(self, collection: Collection) -> None:
        if not holds(collection, Component.EVENT):
            pytest.skip("the collection holds no events")
        [meeting] = self.seed(collection, [Event.new(summary="planning", start=at(5, 9), end=at(5, 10))])
        if self.assert_time_log_unsupported(collection, meeting) or not writable(collection):
            return
        meeting.log_time(start=at(5, 9), end=at(5, 10), users=("mailto:alice@example.com",))
        [entry] = meeting.time_log()
        assert entry.duration == HOUR
        assert collection.reload(meeting) == meeting, "logging time does not touch the meeting itself"

    def test_time_entries_in_a_range(self, collection: Collection) -> None:
        item = self.logged_against(collection)
        if self.assert_time_log_unsupported(collection, item) or not writable(collection):
            return
        if self.total_only(collection) or "start-time" in self.lost(collection):
            pytest.skip("entries without a start cannot be searched by time")
        inside = item.log_time(start=at(10, 9), end=at(10, 10))
        item.log_time(start=at(12, 9), end=at(12, 10))
        found = collection.time_entries(at(10, 0), at(11, 0))
        assert [(uid, e.id) for uid, e in found] == [(item.uid, inside.id)]

    # === moving =======================================================

    def test_move(self, backend: Backend, collection: Collection) -> None:
        task = self.add_task(collection, summary="moving")
        if level(collection, Feature.MOVE) is Support.UNSUPPORTED:
            self.assert_unsupported(collection, Feature.MOVE, lambda: collection.move(task, collection))
            return
        if not backend.capabilities.supports(Feature.CREATE_COLLECTION):
            pytest.skip("a second collection is needed, and the backend cannot make one")
        target = self.open_collection(backend, "conformance-target")
        moved = collection.move(task, target)
        assert moved.collection is target
        assert moved.collection_id == target.id
        with pytest.raises(NotFoundError):
            collection.get_by_native_id(nid(task))
        assert (target.get_by_native_id(nid(moved))).uid == moved.uid

    def test_changes_follow_a_move(self, backend: Backend, collection: Collection) -> None:
        if Support.UNSUPPORTED in (level(collection, Feature.CHANGES), level(collection, Feature.MOVE)):
            return  # the tests of each feature checked that it raises
        task = self.add_task(collection, summary="moving")
        if not backend.capabilities.supports(Feature.CREATE_COLLECTION):
            pytest.skip("a second collection is needed, and the backend cannot make one")
        target = self.open_collection(backend, "conformance-target")
        if level(target, Feature.CHANGES) is Support.UNSUPPORTED:
            pytest.skip("the second collection has no change feed")
        here, there = collection.changes(), target.changes()
        elsewhere = target.add_task(summary="added there")
        moved = collection.move(task, target)
        since_here = collection.changes(here.token)
        since_there = target.changes(there.token)
        assert since_here.deleted == [nid(task)], "a moved item is deleted where it was"
        assert not {nid(elsewhere), nid(moved)} & {nid(i) for i in since_here.changed}
        assert {nid(moved), nid(elsewhere)} <= {nid(i) for i in since_there.changed}
        assert since_there.deleted == []

    # === collections ==================================================

    def test_set_name(self, backend: Backend, collection: Collection) -> None:
        if level(collection, Feature.COLLECTION_SET_NAME) is Support.UNSUPPORTED:
            with pytest.raises(UnsupportedError) as info:
                collection.set_name("renamed")
            assert info.value.feature == Feature.COLLECTION_SET_NAME
            return
        name = collection.name
        collection.set_name("conformance renamed")
        try:
            assert collection.name == "conformance renamed"
            assert (backend.collection(collection.id)).name == "conformance renamed"
        finally:
            if name is not None:  # a borrowed or reused collection is put back as it was
                collection.set_name(name)

    def test_create_and_delete_collection(self, backend: Backend) -> None:
        before = [c.id for c in backend.collections()]
        if backend.capabilities.level(Feature.CREATE_COLLECTION) is Support.UNKNOWN:
            deletable = backend.capabilities.level(Feature.DELETE_COLLECTION) is not Support.UNSUPPORTED
            attempted = None if deletable else self.left_behind(backend, "conformance-new")
            if attempted is None:
                try:
                    attempted = backend.create_collection("conformance-new", components=(Component.TASK,))
                except (UnsupportedError, BackendError):
                    return  # unprobed, and it does not work here: attempted, as UNKNOWN promises
                if deletable:
                    self._made.append(attempted)
            assert attempted.components == frozenset({Component.TASK})
            assert attempted.id in [c.id for c in backend.collections()]
            return
        if not backend.capabilities.supports(Feature.CREATE_COLLECTION):
            with pytest.raises(UnsupportedError) as info:
                backend.create_collection("conformance-new")
            assert info.value.feature == Feature.CREATE_COLLECTION
            assert [c.id for c in backend.collections()] == before
            return
        deletable = backend.capabilities.supports(Feature.DELETE_COLLECTION)
        # Without delete-collection, only the first run on a backend makes it: later ones find it left there.
        made = None if deletable else self.left_behind(backend, "conformance-new")
        if made is None:
            made = backend.create_collection("conformance-new", components=(Component.TASK,))
        assert made.components == frozenset({Component.TASK})
        assert made.id in [c.id for c in backend.collections()]
        if not deletable:
            with pytest.raises(UnsupportedError) as info:
                made.delete_collection()
            assert info.value.feature == Feature.DELETE_COLLECTION
            return
        self._made.append(made)
        made.delete_collection()
        self._made.remove(made)
        assert made.id not in [c.id for c in backend.collections()]

    # === binding ======================================================

    def test_bind_and_as_data(self, collection: Collection) -> None:
        stored = self.add_task(collection, summary="bound")
        data = stored.as_data()
        assert type(data) is Task
        assert not hasattr(data, "collections")
        assert data == stored, "equality compares the data, never the collections"
        assert pickle.loads(pickle.dumps(data)) == data
        with pytest.raises(TypeError):
            pickle.dumps(stored)
        copied = stored.copy()
        assert copied.collection is collection
        assert copied is not stored
        before = snapshot(collection)
        bound = collection.bind(Task.new(summary="not stored"))
        assert isinstance(bound, SyncTask)
        assert bound.collection is collection
        assert snapshot(collection) == before, "bind() did I/O"
